SOURCE_HASHES={'aenv_ub_provider/__init__.py': 'd2874d88f7d86870ee8386ef2f7bad5e451b4fce5beef6c7b488998b0250665b', 'aenv_ub_provider/__main__.py': '1b29b9dcdcba2813c13dd0b616e5942c24aba97be245869ee145a04f47e5d9d9', 'aenv_ub_provider/bindings.py': '7db6061ea42ea652b5efba77ce6f2d89316fd580fcfc737145d1f51ab04ff497', 'aenv_ub_provider/contract.py': '0c47efda619977b708fdb88f9195e49ea7b9bc45c9ec28de75e9173d3cfe8be9', 'aenv_ub_provider/direct.py': '9a102db3d9a9ff607ab3cd79bafd28a2b22325ec62cfffd7cc9aeba994223060', 'aenv_ub_provider/fsdax.py': '6b511945fb1ce68323af28554741a800605948a7c24a5c66e254ff7a3022ec4d', 'aenv_ub_provider/host_dax.py': '62c9664b2cb3951c5a13f4cb1e72cd76f842f577f7156431e5a28672f95362f2', 'aenv_ub_provider/hostfile.py': '5448afb2c4426c0983328b0469327537830b821d1655f713717f81b10dbd93af', 'aenv_ub_provider/io.py': '0a42d175d199e676819c02a1a8594af7e2946c0563f4e966ef902ce2e3f20956', 'aenv_ub_provider/lazy.py': '78936996bbf9b3a61950208da9e03c96fa1fa41517f7add66efb2c942a3c25ee', 'aenv_ub_provider/lazy_service.py': 'f4e87898430d6b51640cce171e6be672fe2530a03d72c7580e72f89285a7f0e3', 'aenv_ub_provider/prebuilt.py': 'ceb383cdecd3dae158abdeefa5717f347367c073d19a281f15f9ac2940df49ff', 'aenv_ub_provider/raw.py': '34206465806358f37b3e0e252b9cea830e6a0d5a8e999a36bead84f9469b99ce', 'aenv_ub_provider/retained.py': '81472cfc0d079a75b3ff632e689fc4d76c5cd570b152a2032010ab38085807d2', 'aenv_ub_provider/sdk.py': 'd7fe2d35aeedb2423cbed387c284a71b5336fe24a221b91aa9e7d30cac0189f3', 'aenv_ub_provider/service.py': '8873975a5a1f13e864659cbf1f14ffb50d581ba5f442739f14bd92cad5753cb8', 'aenv_ub_provider/stored.py': 'a8e07b920594fd9afd3e4bf37a5f1fd04c95807b22856c2d78f7df7e0b84ae02'}
PAYLOAD=''
"""Two-node full stored-lower Host read experiment. Not Guest acceptance.

Explicit owner/import retain providers until explicit B then A retirement.
No remote shell, service change, module change or global cache eviction.
"""
import argparse
import base64
import ctypes
import hashlib
import io
import json
import os
from pathlib import Path
import platform
import re
import socket
import stat
import struct
import subprocess
import sys
import tarfile
import time
import zlib

ROOT = Path('/home/jwk/agent')
ADAPTER_SHA = 'bc53b2e010ebe3a0d69d3f64bad17afee5b7950d06b77d2803565222758ca6d5'
SEED_SHA = {'a': '6247c51df4993d5a6935b7112567989bb189cff2bcf69e874d0154207b0ced15',
            'b': '91d33a86fb12ffa75e6b6af70f327566fc39ac9d7e79e362fbfa0e96a68f2294'}
MIB = 1048576


def need(value, message):
    if not value:
        raise RuntimeError(message)


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def read(path, limit=4*MIB):
    path = Path(path)
    need(path.resolve(strict=True) == path, 'Redirected input path')
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    with os.fdopen(fd, 'rb') as stream:
        m = os.fstat(stream.fileno())
        need(stat.S_ISREG(m.st_mode) and m.st_uid == 1204 and m.st_size <= limit,
             'Unexpected input owner/type/size')
        raw = stream.read(limit + 1)
        n = os.fstat(stream.fileno())
        need((m.st_ino, m.st_size, m.st_mtime_ns, m.st_ctime_ns) ==
             (n.st_ino, n.st_size, n.st_mtime_ns, n.st_ctime_ns), 'Input changed during read')
    return raw


def load(path):
    return json.loads(read(path))


def save(path, value):
    with Path(path).open('x', encoding='utf-8') as stream:
        json.dump(value, stream, indent=2)
        stream.write('\n')
        stream.flush()
        os.fsync(stream.fileno())


def ticks(pid):
    return Path('/proc/' + str(pid) + '/stat').read_text().rsplit(')', 1)[1].split()[19]


def memory():
    return {k.rstrip(':'): int(v[0])*1024 for line in Path('/proc/meminfo').read_text().splitlines()
            for k, *v in [line.split()] if v and k.rstrip(':') in
            ('MemAvailable', 'Cached', 'Buffers', 'AnonPages', 'Slab', 'PageTables')}


def ordinary(node):
    need(sys.platform == 'linux' and platform.machine() == 'aarch64', 'Native ARM64 Linux required')
    need(platform.node() == ('server1' if node == 'a' else 'agent1'), 'Wrong node')
    need(os.getuid() == os.geteuid() == 1204, 'Use jwk, not root')
    caps = [line.split()[1] for line in Path('/proc/self/status').read_text().splitlines()
            if line.startswith(('CapInh:', 'CapPrm:', 'CapEff:', 'CapAmb:'))]
    need(len(caps) == 4 and not any(int(c, 16) for c in caps), 'Zero process capabilities required')


def paths(node):
    return ROOT / 'r' / ('uf-' + node + '-v1')


def package(work):
    for name, expected in SOURCE_HASHES.items():
        need(sha(read(work / 'source' / name, 2*MIB)) == expected, 'Provider source differs')
    sys.path.insert(0, str(work / 'source'))
    from aenv_ub_provider import service, stored, contract
    return service, stored, contract


def unpack(work):
    raw = zlib.decompress(base64.b64decode(PAYLOAD))
    need(sha(raw) == ARCHIVE_SHA256, 'Embedded source differs')
    seen = set()
    with tarfile.open(fileobj=io.BytesIO(raw)) as archive:
        for member in archive:
            need(member.isfile() and member.name in SOURCE_HASHES and member.name not in seen,
                 'Unexpected archive member')
            seen.add(member.name)
            data = archive.extractfile(member).read()
            need(sha(data) == SOURCE_HASHES[member.name], 'Provider member digest differs')
            path = work / 'source' / member.name
            need(not Path(member.name).is_absolute() and '..' not in Path(member.name).parts, 'Invalid member')
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open('xb') as output:
                output.write(data)
    need(seen == set(SOURCE_HASHES), 'Incomplete provider packet')


def selection(node):
    seed_path = ROOT / 'deployments/agentenv-lazy-four-32ce41c/rootfs-inputs.json'
    raw = read(seed_path)
    need(sha(raw) == SEED_SHA[node], 'Retained template inventory differs from returned preparation')
    seed = json.loads(raw)
    need(seed['status'] == 'ORDINARY_FOUR_SNAPSHOTS_SEEDED_NOT_GUEST_ACCEPTANCE', 'Wrong seed mode')
    repo = Path(seed['repository'])
    need(repo.resolve(strict=True) == repo and repo.is_relative_to(ROOT), 'Unexpected repository')
    unique = {}
    for layer in seed['templates'][0]['rootfsLayers']:
        digest, size = layer['digest'], layer['size']
        need(re.fullmatch('sha256:[0-9a-f]{64}', digest) and type(size) is int and size > 0,
             'Invalid lower identity')
        path = repo / 'managed-layers' / (digest.replace(':', '_') + '.overlaybd.commit')
        need(path.resolve(strict=True) == path, 'Redirected lower')
        meta = path.stat()
        need(stat.S_ISREG(meta.st_mode) and meta.st_uid == 1204 and meta.st_size == size, 'Lower changed')
        row = {'digest': digest, 'size': size, 'file': str(path),
               'fileIdentity': [meta.st_dev, meta.st_ino, meta.st_size, meta.st_mtime_ns, meta.st_ctime_ns]}
        need(digest not in unique or unique[digest] == row, 'Conflicting duplicate lower')
        unique[digest] = row
    rows = list(unique.values())
    need(sum(x['size'] for x in rows) == 1742631936, 'Selected full template size changed')
    need(sum((x['size']+4096+4194303)//4194304*4194304 for x in rows) == 1765801984,
         'Full-template allocation layout changed')
    return {'templateIndex': 0, 'sourceRoot': str(repo), 'layers': rows,
            'logicalBytes': 1742631936, 'requestedObjectBytes': 1765801984,
            'postMapCoverageGuardBytes': 4*1024**3, 'physicalHardQuota': False}


def portable(plan):
    return sorted([(x['digest'], x['size']) for x in plan['layers']])


def capsule(value):
    data = json.dumps(value, separators=(',', ':')).encode()
    return base64.urlsafe_b64encode(data).decode()


def decode(text):
    need(len(text) <= 131072, 'Oversized transfer capsule')
    raw = base64.b64decode(text, altchars=b'-_', validate=True)
    return json.loads(raw)


def resident(path, expected):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        m = os.fstat(fd)
        identity = [m.st_dev, m.st_ino, m.st_size, m.st_mtime_ns, m.st_ctime_ns]
        need(identity == expected, 'Observed lower identity changed')
        libc = ctypes.CDLL(None, use_errno=True)
        libc.mmap.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_long]
        libc.mmap.restype = ctypes.c_void_p
        libc.mincore.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p]
        libc.munmap.argtypes = [ctypes.c_void_p, ctypes.c_size_t]
        page = os.sysconf('SC_PAGESIZE')
        total = 0
        # Bounded PROT_NONE windows: observe residency without reading payload.
        for offset in range(0, m.st_size, 64*MIB):
            size = min(64*MIB, m.st_size-offset)
            address = libc.mmap(None, size, 0, 1, fd, offset)
            need(address != ctypes.c_void_p(-1).value, 'Observation mmap failed')
            try:
                bits = (ctypes.c_ubyte * ((size+page-1)//page))()
                need(libc.mincore(address, size, bits) == 0, 'Observation mincore failed')
                total += sum(x & 1 for x in bits)*page
            finally:
                libc.munmap(address, size)
        n = os.fstat(fd)
        need(identity == [n.st_dev, n.st_ino, n.st_size, n.st_mtime_ns, n.st_ctime_ns], 'Lower changed in sample')
        return total
    finally:
        os.close(fd)


def sample(work):
    plan = load(work/'plan.json')
    rows, seen = [], set()
    for layer in plan['layers']:
        key = tuple(layer['fileIdentity'][:2])
        if key in seen:
            continue
        seen.add(key)
        rows.append({'digest': layer['digest'], 'residentBytes': resident(layer['file'], layer['fileIdentity'])})
    return {'atNs': time.time_ns(), 'files': rows, 'lowerResidentBytes': sum(x['residentBytes'] for x in rows),
            'host': memory(), 'atomicSnapshot': False, 'kind': 'whole-selected-files-not-Guest-access-intersection'}


def stable(work):
    owner = load(work/'provider-process.json')
    need(owner['bootId'] == Path('/proc/sys/kernel/random/boot_id').read_text().strip(), 'Boot changed')
    need(ticks(owner['pid']) == owner['startTicks'], 'Provider process changed/exited; preserve unknown resources')
    return owner


def control(work, request):
    stable(work)
    _, _, contract = package(work)
    with socket.socket(socket.AF_UNIX) as stream:
        stream.settimeout(600)
        stream.connect(str(work/'p/control.sock'))
        contract.same_uid(stream)
        contract.send_json(stream, request)
        result = contract.receive_json(stream)
    return result


def provider_inside(work):
    import fcntl
    node = load(work/'context.json')['node']
    ordinary(node)
    lockpath = ROOT/'relay'/('ub-layer-sdk-node-'+node+'.lock')
    need(lockpath.parent.resolve(strict=True) == lockpath.parent, 'Missing/redirected SDK lock directory')
    fd = os.open(lockpath, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
    try:
        m = os.fstat(fd)
        need(stat.S_ISREG(m.st_mode) and m.st_uid == 1204 and m.st_nlink == 1, 'SDK lock differs')
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        service, _, _ = package(work)
        config = service.load_config(work/'provider.json')
        selected, manifest = service.inputs(config)
        service.serve(config, selected, manifest)
    finally:
        os.close(fd)


def start(node, imported=None):
    work = paths(node)
    need(work.parent.resolve(strict=True) == work.parent and not work.exists() and not work.is_symlink(),
         'Existing full-generation directory preserved; never blindly repeat start')
    old = load(ROOT/'r'/('ud-'+node+'-v1')/'preparation-report.json')
    need(old['status'] == 'DIRECT_UB_NATIVE_PREPARED_NOT_DEPLOYED' and old['node'] == node,
         'Native preparation missing')
    adapter = ROOT/'r'/('ud-'+node+'-v1')/'libaenv-ub.so'
    need(sha(read(adapter)) == ADAPTER_SHA, 'Prepared adapter changed')
    plan = selection(node)
    need(memory()['MemAvailable'] >= 8*1024**3, 'Require 8GiB MemAvailable headroom before new full experiment')
    if imported is not None:
        need(imported.get('kind') == 'direct-full-owner-v1' and imported['layers'] == [list(x) for x in portable(plan)],
             'Peer template layer identity/order-independent set differs')
        manifest = imported['manifest']
        need(manifest['mode'] == 'stored-direct' and manifest['readers'] == ['full-b-v1'], 'Wrong owner generation')
    os.umask(0o077)
    work.mkdir(mode=0o700)
    unpack(work)
    save(work/'context.json', {'node': node, 'bootId': Path('/proc/sys/kernel/random/boot_id').read_text().strip(),
                              'coreCommit': CORE, 'stage': 'full-host-lower-read-not-Guest'})
    save(work/'plan.json', plan)
    save(work/'before-publication.json', sample(work))
    config = {'version': 1, 'mode': 'stored-direct', 'role': 'publish' if node == 'a' else 'import',
        'workDir': str(work/'p'), 'adapter': str(adapter), 'adapterSha256': 'sha256:'+ADAPTER_SHA,
        'region': 'default', 'logicalBudgetBytes': 2*1024**3, 'maxCoverageBytes': 4*1024**3}
    if node == 'a':
        save(work/'image.json', {'lowers': [{k:v for k,v in x.items() if k != 'fileIdentity'} for x in plan['layers']]})
        config.update(readers=['full-b-v1'], sourceRoot=plan['sourceRoot'], images=[str(work/'image.json')])
    else:
        save(work/'owner-manifest.json', manifest)
        config.update(readerId='full-b-v1', manifest=str(work/'owner-manifest.json'))
    save(work/'provider.json', config)
    data = Path(__file__).read_bytes()
    with (work/'entry.py').open('xb') as output:
        output.write(data)
    save(work/'start-intent.json', {'state':'intent_before_process_start','entrySha256':sha(data)})
    with (work/'provider.log').open('xb') as log:
        child = subprocess.Popen([sys.executable, '-I', '-B', str(work/'entry.py'),
            'provider-inside', '--node', node, '--run'], stdin=subprocess.DEVNULL,
            stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
    save(work/'provider-process.json', {'pid':child.pid, 'startTicks':ticks(child.pid),
        'bootId':Path('/proc/sys/kernel/random/boot_id').read_text().strip()})
    begin, last = time.monotonic(), 0
    while time.monotonic()-begin < 1800:
        elapsed = int(time.monotonic()-begin)
        if elapsed-last >= 20:
            print('PROGRESS full-publication-or-import elapsed_s='+str(elapsed), flush=True)
            last = elapsed
        need(child.poll() is None, 'Provider stopped; preserve directory and provider.log, no new generation')
        if (work/'p/control.sock').exists() and (work/'p/owner.json').exists():
            if load(work/'p/owner.json').get('state') == 'serving':
                break
        time.sleep(1)
    else:
        raise RuntimeError('Provider readiness deadline reached; process/object state preserved, do not repeat start')
    status = control(work, {'operation':'status'})
    evidence = load(work/'p/mapping-evidence.json')
    need(evidence['allocationCalls'] == (len(plan['layers']) if node == 'a' else 0), 'Unexpected allocation calls')
    result = {'status':'DIRECT_FULL_HOST_PROVIDER_READY', 'node':node, 'workDirectory':str(work),
        'provider':status, 'mappingEvidence':evidence, 'afterPublication':sample(work),
        'Guest_created':False, 'servicesChanged':False, 'kernelChanged':False,
        'physicalSharingAccepted':False, 'netSavingsBytes':None, 'providerRetainedForNextStep':True}
    save(work/'ready-report.json', result)
    if node == 'a':
        transfer = {'kind':'direct-full-owner-v1','layers':[list(x) for x in portable(plan)],
                    'manifest':load(work/'p/replicas.json')}
        save(work/'owner-transfer.json', transfer)
        result['importCapsule'] = capsule(transfer)
    return result


def read_ub(work, layer, replica):
    _, stored, _ = package(work)
    total = hashlib.sha256()
    with socket.socket(socket.AF_UNIX) as stream:
        stream.settimeout(60)
        stream.connect(replica['brokerSocket'])
        name = replica['objectName'].encode()
        stream.sendall(stored.MAGIC+struct.pack('>H',len(name))+name+
            bytes.fromhex(replica['generation'])+struct.pack('>QQ',replica['fileBytes'],replica['mappingBytes'])+
            bytes.fromhex(replica['layerDigest'][7:]))
        need(stored.RESPONSE.unpack(stored.recv_exact(stream,16)) == (stored.MAGIC,0,0), 'Broker lease refused')
        for offset in range(0, layer['size'], MIB):
            size = min(MIB, layer['size']-offset)
            stream.sendall(struct.pack('>QI',offset,size))
            need(stored.RESPONSE.unpack(stored.recv_exact(stream,16)) == (stored.MAGIC,0,size), 'Broker read failed')
            total.update(stored.recv_exact(stream,size))
    return 'sha256:'+total.hexdigest()


def read_file(layer):
    path=Path(layer['file'])
    need(path.resolve(strict=True)==path,'Redirected reference lower')
    fd=os.open(path,os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_NONBLOCK)
    h=hashlib.sha256()
    with os.fdopen(fd,'rb') as stream:
        m=os.fstat(stream.fileno())
        need([m.st_dev,m.st_ino,m.st_size,m.st_mtime_ns,m.st_ctime_ns]==layer['fileIdentity'],
             'Reference lower identity changed')
        for data in iter(lambda:stream.read(MIB),b''):
            h.update(data)
        n=os.fstat(stream.fileno())
        need([n.st_dev,n.st_ino,n.st_size,n.st_mtime_ns,n.st_ctime_ns]==layer['fileIdentity'],
             'Reference lower changed during read')
    return 'sha256:'+h.hexdigest()


def measure(node):
    work = paths(node)
    need(not (work/'read-intent.json').exists(), 'Previous measurement preserved; no implicit repeat')
    plan = load(work/'plan.json')
    index = load(work/'p/runtime-index.json')
    refs = {x['layerDigest']:x for x in index['replicas']}
    need(sorted((k,v['fileBytes']) for k,v in refs.items()) == portable(plan), 'Runtime index differs')
    stable(work)
    save(work/'read-intent.json', {'state':'intent_before_full_ub_read','atNs':time.time_ns()})
    result = {'status':'DIRECT_FULL_HOST_READ_RUNNING','node':node,
        'ownerId':load(work/'p/replicas.json')['ownerId'], 'layers':portable(plan),
        'beforeUB':sample(work), 'providerBefore':control(work,{'operation':'status'}),
        'reads':[], 'Guest_created':False, 'guestAcceptance':False,
        'physicalSharingAccepted':False, 'netSavingsBytes':None,
        'scope':'sequential full stored lower reads through broker; not Guest workload'}
    begin = time.monotonic()
    for i, layer in enumerate(plan['layers']):
        print('PHASE=ub-lower-'+str(i),flush=True)
        got = read_ub(work,layer,refs[layer['digest']])
        need(got == layer['digest'], 'UB contents differ')
        result['reads'].append({'digest':got,'bytes':layer['size'],'source':'ub-broker'})
    result['ubReadSeconds'] = time.monotonic()-begin
    result['afterUB'] = sample(work)
    result['providerAfter'] = control(work,{'operation':'status'})
    # Buffered comparison is explicit and occurs AFTER the UB-only observation.
    # No drop_caches or fadvise against real/retained lower files.
    save(work/'ub-read-complete.json', result)
    begin = time.monotonic()
    for i, layer in enumerate(plan['layers']):
        print('PHASE=buffered-reference-lower-'+str(i),flush=True)
        need(read_file(layer) == layer['digest'], 'Buffered reference contents differ')
    result['bufferedReadSeconds'] = time.monotonic()-begin
    result['afterBuffered'] = sample(work)
    result['ubFileResidencyDeltaBytes'] = result['afterUB']['lowerResidentBytes']-result['beforeUB']['lowerResidentBytes']
    result['subsequentBufferedResidencyDeltaBytes'] = result['afterBuffered']['lowerResidentBytes']-result['afterUB']['lowerResidentBytes']
    result['cacheInterpretation'] = ('cold-selected-files-remained-nonresident-during-UB-read'
        if result['beforeUB']['lowerResidentBytes'] == result['afterUB']['lowerResidentBytes'] == 0
        else 'existing-residency-or-background-change; no-cold-cache-saving-claim')
    result['status'] = 'DIRECT_FULL_HOST_READ_AND_BUFFERED_REFERENCE_COMPLETED_NOT_GUEST_ACCEPTANCE'
    stable(work)
    save(work/'host-read-report.json',result)
    return result


def retire(node, peer):
    work = paths(node)
    request = {'operation':'retire','peerReceipts':[]}
    if node == 'a':
        need(peer is not None, 'Owner requires explicit B release capsule')
        receipt = decode(peer)
        _, _, _ = package(work)
        need(receipt.get('state') == 'released', 'B release incomplete')
        path = work/'b-release.json'
        if path.exists():
            need(load(path) == receipt, 'Existing B release differs; preserved')
        else:
            save(path,receipt)
        request['peerReceipts']=[str(path)]
    else:
        need(peer is None, 'Importer never accepts owner deletion authority')
    result = control(work,request)
    need(result.get('state') == 'released', 'Provider retirement refused; preserve resources')
    result.update(node=node, Guest_created=False, scope='provider retirement only')
    if node == 'b':
        result['releaseCapsule']=capsule(load(work/'p/release.json'))
    return result


def root_evidence(node):
    need(os.geteuid()==0 and platform.node()==('server1' if node=='a' else 'agent1'),
         'Read-only mapping evidence requires the declared node root')
    work=paths(node)
    owner=stable(work)
    pid=owner['pid']
    status=Path('/proc/'+str(pid)+'/status').read_text()
    uid=next(line.split()[1:] for line in status.splitlines() if line.startswith('Uid:'))
    need(uid==['1204']*4,'Provider UID differs')
    evidence=load(work/'p/mapping-evidence.json')
    devices={row['device'] for mapping in evidence['mappings'] for row in mapping['segments']}
    need(all(re.fullmatch('/dev/obmm_shmdev[0-9]+',x) for x in devices),'Invalid mapped device name')
    maps=[]
    for line in Path('/proc/'+str(pid)+'/maps').read_text().splitlines():
        fields=line.split()
        if len(fields)>=6 and fields[-1] in devices:
            lo,hi=(int(x,16) for x in fields[0].split('-'))
            maps.append({'device':fields[-1],'bytes':hi-lo,'permissions':fields[1],
                         'offset':int(fields[2],16)})
    rows=[]
    for name in sorted(devices):
        root=Path('/sys/devices/obmm')/Path(name).name
        row={'device':name}
        for field in ('type','size','allow_mmap','export_info/node_mem_size','export_info/deid',
                      'import_info/seid','import_info/deid','import_info/scna','import_info/dcna'):
            try:
                value=(root/field).read_text().strip()
                need(len(value)<=1024,'Oversized sysfs attribute')
                row[field]=value
            except (FileNotFoundError,PermissionError) as error:
                row[field]={'NA':type(error).__name__}
        rows.append(row)
    stable(work)
    return {'status':'DIRECT_FULL_READONLY_MAPPING_EVIDENCE','node':node,
        'ownerId':evidence['ownerId'],'manifestSha256':evidence['manifestSha256'],
        'allocationCalls':evidence['allocationCalls'],'objectMappings':evidence['mappings'],
        'providerVmas':maps,'regions':rows,'host':memory(),
        'readOnly':True,'physicalSharingAccepted':False,'netSavingsBytes':None,
        'scope':'object/device/VMA/region evidence; pair across nodes before acceptance'}


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('mode',choices=('owner','import','measure','status','retire','provider-inside','root-evidence'))
    parser.add_argument('--node',choices=('a','b'),required=True)
    parser.add_argument('--capsule')
    parser.add_argument('--run',action='store_true')
    args=parser.parse_args()
    if not args.run:
        print(json.dumps({'status':'DIRECT_FULL_HOST_PLAN_NO_ACTION','mode':args.mode,'node':args.node,
            'logicalBytes':1742631936,'requestedObjectBytes':1765801984,
            'postMapCoverageGuardBytes':4*1024**3,'physicalHardQuota':False,
            'noGuestOrKernelChange':True,'providerRetainedUntilExplicitRetire':True},indent=2))
        return 0
    if args.mode=='root-evidence':
        result=root_evidence(args.node)
        print('BEGIN_DIRECT_FULL_MAPPING_REPORT')
        print(json.dumps(result,indent=2))
        print('END_DIRECT_FULL_MAPPING_REPORT')
        return 0
    ordinary(args.node)
    if args.mode=='provider-inside':
        provider_inside(paths(args.node))
        return 0
    operation_fd = None
    try:
        if args.mode in ('measure','retire'):
            import fcntl
            operation_fd = os.open(paths(args.node)/'operation.lock',
                os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW | os.O_CLOEXEC,0o600)
            meta=os.fstat(operation_fd)
            need(stat.S_ISREG(meta.st_mode) and meta.st_uid==1204 and meta.st_nlink==1,'Unexpected operation lock')
            fcntl.flock(operation_fd,fcntl.LOCK_EX | fcntl.LOCK_NB)
        if args.mode=='owner':
            need(args.node=='a' and args.capsule is None,'Owner only on A')
            result=start('a')
        elif args.mode=='import':
            need(args.node=='b' and args.capsule is not None,'Import only on B with owner capsule')
            result=start('b',decode(args.capsule))
        elif args.mode=='measure':
            result=measure(args.node)
        elif args.mode=='status':
            result=control(paths(args.node),{'operation':'status'})
        else:
            result=retire(args.node,args.capsule)
        code=0
    except Exception as error:
        result={'status':'STOPPED_DIRECT_FULL_HOST_PRESERVE_STATE','node':args.node,
                'reason':str(error),'errorType':type(error).__name__,
                'workDirectory':str(paths(args.node)), 'automaticRecoveryExecuted':False,
                'netSavingsBytes':None,'Guest_created':False}
        code=1
    finally:
        if operation_fd is not None:
            os.close(operation_fd)
    print('BEGIN_DIRECT_FULL_HOST_REPORT')
    print(json.dumps(result,indent=2))
    print('END_DIRECT_FULL_HOST_REPORT')
    return code


if __name__=='__main__':
    raise SystemExit(main())
